schema_ddl:
CREATE TABLE MONTHS (MID INT, MONTH INT);
CREATE TABLE WEEKDAYS (DID INT, DAY_OF_WEEK INT);
CREATE TABLE CARRIERS (CID INT, NAME INT);
CREATE TABLE FLIGHTS (FID INT, YEAR INT, MONTH_ID INT, DAY_OF_MONTH INT, CARRIER_ID INT);

counterexample:
INSERT INTO CARRIERS (CID, NAME) VALUES (1, 100);
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) VALUES (1, 2020, 1, 1, 1);
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID) VALUES (2, 2021, 1, 1, 1);

